-- =====================================================================
-- V1__baseline.sql — Kazi tenant schema baseline
-- Phase 86 squash. Generated by dump-and-clean of a fresh schema migrated with the full
-- pre-squash series (Flyway 11.14.1, PostgreSQL 16) at commit a99b11f50 (main, 2026-10-18),
-- post-removal; proven equal to a TenantProvisioningService-provisioned tenant by
-- BaselineSchemaParityTest.
-- Supersedes tenant V1..V144 (133 files + 9 Phase 86 drop migrations V136..V144),
-- archived at git tag `horizontal-platform-final`.
-- RULE: this file is immutable once the first production tenant exists.
--       Never squash again; add V2+ feature migrations. See backend/db/BASELINE.md.
-- Hand-cleaned: no pg_dump noise, deterministic order, all chk_/uq_/idx_/fk_ names preserved.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Tables (FK-dependency order; constraints inline)
-- ---------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS acceptance_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    generated_document_id uuid NOT NULL,
    portal_contact_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    request_token character varying(255) NOT NULL,
    sent_at timestamp with time zone,
    viewed_at timestamp with time zone,
    accepted_at timestamp with time zone,
    expires_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    acceptor_name character varying(255),
    acceptor_ip_address character varying(45),
    acceptor_user_agent character varying(500),
    certificate_s3_key character varying(1000),
    certificate_file_name character varying(255),
    sent_by_member_id uuid NOT NULL,
    revoked_by_member_id uuid,
    reminder_count integer DEFAULT 0 NOT NULL,
    last_reminded_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT acceptance_requests_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS accounting_sync_entry (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_type character varying(20) NOT NULL,
    entity_id uuid NOT NULL,
    provider_id character varying(20) NOT NULL,
    direction character varying(10) NOT NULL,
    state character varying(30) DEFAULT 'PENDING'::character varying NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone,
    last_error_code character varying(50),
    last_error_detail text,
    external_reference character varying(100),
    external_id character varying(100),
    trigger character varying(30) DEFAULT 'EVENT'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT ck_ase_direction CHECK ((direction IN ('PUSH', 'PULL'))),
    CONSTRAINT ck_ase_entity_type CHECK ((entity_type IN ('INVOICE', 'CUSTOMER', 'PAYMENT_PULL'))),
    CONSTRAINT ck_ase_state CHECK ((state IN ('PENDING', 'IN_FLIGHT', 'COMPLETED', 'FAILED_RETRYING', 'DEAD_LETTER', 'BLOCKED_TRUST_BOUNDARY', 'RECONCILE_DRIFT'))),
    CONSTRAINT ck_ase_trigger CHECK ((trigger IN ('EVENT', 'MANUAL_RETRY', 'FORCE_RESYNC'))),
    CONSTRAINT accounting_sync_entry_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS accounting_tax_code_mapping (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider_id character varying(20) NOT NULL,
    kazi_tax_mode character varying(30) NOT NULL,
    external_tax_code character varying(50) NOT NULL,
    display_label character varying(100) NOT NULL,
    is_default boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_atcm_kazi_tax_mode CHECK ((kazi_tax_mode IN ('STANDARD_15', 'ZERO_RATED', 'EXEMPT', 'OUT_OF_SCOPE', 'STANDARD_OTHER'))),
    CONSTRAINT accounting_tax_code_mapping_pkey PRIMARY KEY (id),
    CONSTRAINT uq_atcm_provider_tax_mode UNIQUE (provider_id, kazi_tax_mode)
);

CREATE TABLE IF NOT EXISTS adverse_parties (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(300) NOT NULL,
    id_number character varying(20),
    registration_number character varying(30),
    party_type character varying(20) NOT NULL,
    aliases text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT adverse_parties_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS ai_executions (
    id uuid NOT NULL,
    skill_id character varying(40) NOT NULL,
    entity_type character varying(30) NOT NULL,
    entity_id uuid NOT NULL,
    status character varying(20) NOT NULL,
    input_summary text,
    output_content text,
    model character varying(40) NOT NULL,
    input_tokens integer DEFAULT 0 NOT NULL,
    output_tokens integer DEFAULT 0 NOT NULL,
    cache_read_input_tokens integer DEFAULT 0 NOT NULL,
    cache_creation_input_tokens integer DEFAULT 0 NOT NULL,
    cost_cents bigint DEFAULT 0 NOT NULL,
    duration_ms bigint,
    invoked_by uuid,
    firm_profile_version integer,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ai_executions_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS ai_firm_profiles (
    id uuid NOT NULL,
    practice_areas jsonb DEFAULT '[]'::jsonb NOT NULL,
    jurisdiction character varying(10) DEFAULT 'ZA'::character varying NOT NULL,
    risk_calibration character varying(20) DEFAULT 'CONSERVATIVE'::character varying NOT NULL,
    house_style_notes text,
    fica_requirements jsonb DEFAULT '{}'::jsonb,
    fee_estimation_notes text,
    preferred_model character varying(40) DEFAULT 'claude-sonnet-4-6'::character varying NOT NULL,
    monthly_budget_cents bigint,
    profile_version integer DEFAULT 1 NOT NULL,
    cold_start_completed boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    CONSTRAINT ai_firm_profiles_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS audit_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_type character varying(100) NOT NULL,
    entity_type character varying(50) NOT NULL,
    entity_id uuid NOT NULL,
    actor_id uuid,
    actor_type character varying(20) DEFAULT 'USER'::character varying NOT NULL,
    source character varying(30) NOT NULL,
    ip_address character varying(45),
    user_agent character varying(500),
    details jsonb,
    occurred_at timestamp with time zone NOT NULL,
    CONSTRAINT audit_events_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS billing_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(300),
    status character varying(20) DEFAULT 'PREVIEW'::character varying NOT NULL,
    period_from date NOT NULL,
    period_to date NOT NULL,
    currency character varying(3) NOT NULL,
    include_expenses boolean DEFAULT true NOT NULL,
    total_customers integer,
    total_invoices integer,
    total_amount numeric(14,2),
    total_sent integer,
    total_failed integer,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT billing_runs_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS checklist_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(200) NOT NULL,
    slug character varying(200) NOT NULL,
    description text,
    customer_type character varying(20) NOT NULL,
    source character varying(20) DEFAULT 'ORG_CUSTOM'::character varying NOT NULL,
    pack_id character varying(100),
    pack_template_key character varying(100),
    active boolean DEFAULT true NOT NULL,
    auto_instantiate boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_checklist_templates_pack CHECK ((((pack_id IS NULL) AND (pack_template_key IS NULL)) OR ((pack_id IS NOT NULL) AND (pack_template_key IS NOT NULL)))),
    CONSTRAINT chk_checklist_templates_slug CHECK (((slug)::text ~ '^[a-z][a-z0-9-]*$'::text)),
    CONSTRAINT checklist_templates_pkey PRIMARY KEY (id),
    CONSTRAINT uq_checklist_templates_slug UNIQUE (slug)
);

CREATE TABLE IF NOT EXISTS clauses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title character varying(200) NOT NULL,
    slug character varying(200) NOT NULL,
    description character varying(500),
    category character varying(100) NOT NULL,
    source character varying(20) DEFAULT 'CUSTOM'::character varying NOT NULL,
    source_clause_id uuid,
    pack_id character varying(100),
    active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    body jsonb,
    legacy_body text,
    CONSTRAINT clauses_slug_format CHECK (((slug)::text ~ '^[a-z][a-z0-9-]*$'::text)),
    CONSTRAINT clauses_source_check CHECK ((source IN ('SYSTEM', 'CLONED', 'CUSTOM'))),
    CONSTRAINT clauses_pkey PRIMARY KEY (id),
    CONSTRAINT clauses_slug_unique UNIQUE (slug)
);

CREATE TABLE IF NOT EXISTS collection_activities (
    id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    stage character varying(20) NOT NULL,
    status character varying(20) NOT NULL,
    gate_id uuid,
    email_delivery_log_id uuid,
    days_overdue_at_action integer NOT NULL,
    reason character varying(255),
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version integer DEFAULT 0 NOT NULL,
    CONSTRAINT ck_collection_stage CHECK ((stage IN ('STAGE_1', 'STAGE_2', 'STAGE_3', 'ESCALATION'))),
    CONSTRAINT ck_collection_status CHECK ((status IN ('PROPOSED', 'SENT', 'SEND_FAILED', 'REJECTED', 'CANCELLED_PAYMENT', 'SKIPPED', 'FLAGGED'))),
    CONSTRAINT collection_activities_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS correspondence (
    id uuid NOT NULL,
    customer_id uuid,
    project_id uuid,
    direction character varying(10) DEFAULT 'INBOUND'::character varying NOT NULL,
    subject character varying(500),
    body_text text,
    body_html text,
    from_address character varying(320) NOT NULL,
    to_addresses jsonb,
    cc_addresses jsonb,
    sent_at timestamp with time zone,
    received_at timestamp with time zone,
    thread_key character varying(255),
    message_id character varying(512) NOT NULL,
    source character varying(30) DEFAULT 'MCP'::character varying NOT NULL,
    filed_by_member_id uuid NOT NULL,
    filed_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version integer DEFAULT 0 NOT NULL,
    CONSTRAINT chk_correspondence_linkage CHECK (((customer_id IS NOT NULL) OR (project_id IS NOT NULL))),
    CONSTRAINT correspondence_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS email_delivery_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    recipient_email character varying(320) NOT NULL,
    template_name character varying(100) NOT NULL,
    reference_type character varying(30) NOT NULL,
    reference_id uuid,
    status character varying(20) NOT NULL,
    provider_message_id character varying(200),
    provider_slug character varying(50) NOT NULL,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_email_delivery_reference_type CHECK ((reference_type IN ('NOTIFICATION', 'INVOICE', 'MAGIC_LINK', 'TEST', 'ACCEPTANCE_REQUEST', 'INFORMATION_REQUEST', 'PORTAL_DIGEST', 'PORTAL_TRUST_ACTIVITY', 'PORTAL_DEADLINE', 'PORTAL_DOCUMENT_READY', 'COLLECTION_REMINDER', 'CASH_DIGEST'))),
    CONSTRAINT chk_email_delivery_status CHECK ((status IN ('SENT', 'DELIVERED', 'BOUNCED', 'FAILED', 'RATE_LIMITED'))),
    CONSTRAINT email_delivery_log_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS expenses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    task_id uuid,
    member_id uuid NOT NULL,
    date date NOT NULL,
    description character varying(500) NOT NULL,
    amount numeric(12,2) NOT NULL,
    currency character varying(3) NOT NULL,
    category character varying(30) NOT NULL,
    receipt_document_id uuid,
    billable boolean DEFAULT true NOT NULL,
    invoice_id uuid,
    markup_percent numeric(5,2),
    notes character varying(1000),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT expenses_amount_positive CHECK ((amount > (0)::numeric)),
    CONSTRAINT expenses_category_check CHECK ((category IN ('FILING_FEE', 'TRAVEL', 'COURIER', 'SOFTWARE', 'SUBCONTRACTOR', 'PRINTING', 'COMMUNICATION', 'OTHER'))),
    CONSTRAINT expenses_markup_non_negative CHECK (((markup_percent IS NULL) OR (markup_percent >= (0)::numeric))),
    CONSTRAINT expenses_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS field_date_notification_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_type character varying(20) NOT NULL,
    entity_id uuid NOT NULL,
    field_name character varying(100) NOT NULL,
    days_until integer NOT NULL,
    fired_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT field_date_notification_log_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS field_definitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_type character varying(20) NOT NULL,
    name character varying(100) NOT NULL,
    slug character varying(100) NOT NULL,
    field_type character varying(20) NOT NULL,
    description text,
    required boolean DEFAULT false NOT NULL,
    default_value jsonb,
    options jsonb,
    validation jsonb,
    sort_order integer DEFAULT 0 NOT NULL,
    pack_id character varying(100),
    pack_field_key character varying(100),
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    visibility_condition jsonb,
    required_for_contexts jsonb DEFAULT '[]'::jsonb NOT NULL,
    portal_visible_deadline boolean DEFAULT false NOT NULL,
    CONSTRAINT field_definitions_pkey PRIMARY KEY (id),
    CONSTRAINT uq_field_def_type_slug UNIQUE (entity_type, slug)
);

CREATE TABLE IF NOT EXISTS field_groups (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_type character varying(20) NOT NULL,
    name character varying(100) NOT NULL,
    slug character varying(100) NOT NULL,
    description text,
    pack_id character varying(100),
    sort_order integer DEFAULT 0 NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    auto_apply boolean DEFAULT false NOT NULL,
    depends_on jsonb,
    applicable_work_types jsonb,
    applicable_entity_values jsonb,
    CONSTRAINT field_groups_pkey PRIMARY KEY (id),
    CONSTRAINT uq_field_group_type_slug UNIQUE (entity_type, slug)
);

CREATE TABLE IF NOT EXISTS invoice_counters (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    next_number integer DEFAULT 1 NOT NULL,
    singleton boolean DEFAULT true NOT NULL,
    CONSTRAINT chk_counter_positive CHECK ((next_number > 0)),
    CONSTRAINT chk_singleton CHECK ((singleton = true)),
    CONSTRAINT invoice_counters_pkey PRIMARY KEY (id),
    CONSTRAINT invoice_counters_singleton UNIQUE (singleton)
);

CREATE TABLE IF NOT EXISTS mcp_egress_consents (
    id uuid NOT NULL,
    consented_by uuid NOT NULL,
    consented_at timestamp with time zone NOT NULL,
    consent_version text NOT NULL,
    action text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mcp_egress_consents_action_check CHECK ((action = ANY (ARRAY['GRANTED'::text, 'REVOKED'::text]))),
    CONSTRAINT mcp_egress_consents_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS org_integrations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    domain character varying(30) NOT NULL,
    provider_slug character varying(50) NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    config_json jsonb,
    key_suffix character varying(6),
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT org_integrations_pkey PRIMARY KEY (id),
    CONSTRAINT uq_org_integrations_domain UNIQUE (domain)
);

CREATE TABLE IF NOT EXISTS org_roles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(100) NOT NULL,
    slug character varying(100) NOT NULL,
    description character varying(500),
    is_system boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT org_roles_pkey PRIMARY KEY (id),
    CONSTRAINT uq_org_roles_slug UNIQUE (slug)
);

CREATE TABLE IF NOT EXISTS org_secrets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    secret_key character varying(200) NOT NULL,
    encrypted_value text NOT NULL,
    iv character varying(24) NOT NULL,
    key_version integer DEFAULT 1 NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT org_secrets_pkey PRIMARY KEY (id),
    CONSTRAINT uq_org_secrets_key UNIQUE (secret_key)
);

CREATE TABLE IF NOT EXISTS org_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    default_currency character varying(3) DEFAULT 'USD'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    field_pack_status jsonb,
    logo_s3_key character varying(500),
    brand_color character varying(7),
    document_footer_text text,
    template_pack_status jsonb,
    dormancy_threshold_days integer DEFAULT 90,
    data_request_deadline_days integer DEFAULT 30,
    compliance_pack_status jsonb,
    report_pack_status jsonb,
    accounting_enabled boolean DEFAULT false NOT NULL,
    ai_enabled boolean DEFAULT false NOT NULL,
    document_signing_enabled boolean DEFAULT false NOT NULL,
    tax_registration_number character varying(50),
    tax_registration_label character varying(30) DEFAULT 'Tax Number'::character varying,
    tax_label character varying(20) DEFAULT 'Tax'::character varying,
    tax_inclusive boolean DEFAULT false NOT NULL,
    clause_pack_status jsonb,
    acceptance_expiry_days integer,
    time_reminder_enabled boolean DEFAULT false NOT NULL,
    time_reminder_days character varying(50) DEFAULT 'MON,TUE,WED,THU,FRI'::character varying,
    time_reminder_time time without time zone DEFAULT '17:00:00'::time without time zone,
    time_reminder_min_minutes integer DEFAULT 240,
    default_expense_markup_percent numeric(5,2),
    request_pack_status jsonb,
    default_request_reminder_days integer DEFAULT 5,
    automation_pack_status jsonb,
    billing_batch_async_threshold integer DEFAULT 50 NOT NULL,
    billing_email_rate_limit integer DEFAULT 5 NOT NULL,
    default_billing_run_currency character varying(3),
    project_naming_pattern character varying(500),
    onboarding_dismissed_at timestamp with time zone,
    vertical_profile character varying(50),
    enabled_modules jsonb DEFAULT '[]'::jsonb,
    terminology_namespace character varying(100),
    data_protection_jurisdiction character varying(10),
    retention_policy_enabled boolean DEFAULT false NOT NULL,
    default_retention_months integer,
    financial_retention_months integer DEFAULT 60,
    information_officer_name character varying(255),
    information_officer_email character varying(255),
    project_template_pack_status jsonb,
    legal_matter_retention_years integer DEFAULT 5,
    portal_digest_cadence character varying(12) DEFAULT 'WEEKLY'::character varying,
    digest_last_sent_at timestamp with time zone,
    portal_notification_doc_types jsonb DEFAULT '["matter-closure-letter", "statement-of-account"]'::jsonb NOT NULL,
    collections_enabled boolean DEFAULT false NOT NULL,
    collections_stage1_days integer,
    collections_stage2_days integer,
    collections_stage3_days integer,
    collections_escalate_days integer,
    CONSTRAINT chk_brand_color_format CHECK (((brand_color IS NULL) OR ((brand_color)::text ~ '^#[0-9a-fA-F]{6}$'::text))),
    CONSTRAINT chk_brand_color_hex CHECK (((brand_color IS NULL) OR ((brand_color)::text ~ '^#[0-9a-fA-F]{6}$'::text))),
    CONSTRAINT chk_org_settings_currency_len CHECK ((char_length((default_currency)::text) = 3)),
    CONSTRAINT org_settings_legal_matter_retention_years_check CHECK (((legal_matter_retention_years IS NULL) OR (legal_matter_retention_years >= 1))),
    CONSTRAINT org_settings_portal_digest_cadence_check CHECK ((portal_digest_cadence IN ('WEEKLY', 'BIWEEKLY', 'OFF'))),
    CONSTRAINT org_settings_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS pack_install (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    pack_id character varying(128) NOT NULL,
    pack_type character varying(64) NOT NULL,
    pack_version character varying(32) NOT NULL,
    pack_name character varying(256) NOT NULL,
    installed_at timestamp with time zone DEFAULT now() NOT NULL,
    installed_by_member_id uuid,
    item_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT pack_install_pkey PRIMARY KEY (id),
    CONSTRAINT uq_pack_install_pack_id UNIQUE (pack_id)
);

CREATE TABLE IF NOT EXISTS processing_activities (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    category character varying(100) NOT NULL,
    description text NOT NULL,
    legal_basis character varying(50) NOT NULL,
    data_subjects character varying(255) NOT NULL,
    retention_period character varying(100) NOT NULL,
    recipients character varying(255),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT processing_activities_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS report_definitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(200) NOT NULL,
    slug character varying(100) NOT NULL,
    description text,
    category character varying(50) NOT NULL,
    parameter_schema jsonb DEFAULT '{"parameters": []}'::jsonb NOT NULL,
    column_definitions jsonb DEFAULT '{"columns": []}'::jsonb NOT NULL,
    template_body text NOT NULL,
    is_system boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT report_definitions_pkey PRIMARY KEY (id),
    CONSTRAINT uq_report_definitions_slug UNIQUE (slug)
);

CREATE TABLE IF NOT EXISTS request_counters (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    next_number integer DEFAULT 1 NOT NULL,
    singleton boolean DEFAULT true NOT NULL,
    CONSTRAINT chk_request_counter_positive CHECK ((next_number > 0)),
    CONSTRAINT chk_request_counter_singleton CHECK ((singleton = true)),
    CONSTRAINT request_counters_pkey PRIMARY KEY (id),
    CONSTRAINT request_counters_singleton UNIQUE (singleton)
);

CREATE TABLE IF NOT EXISTS request_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(200) NOT NULL,
    description character varying(1000),
    source character varying(20) DEFAULT 'CUSTOM'::character varying NOT NULL,
    pack_id character varying(100),
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT request_templates_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS retention_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    record_type character varying(20) NOT NULL,
    retention_days integer NOT NULL,
    trigger_event character varying(30) NOT NULL,
    action character varying(20) DEFAULT 'FLAG'::character varying NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    description text,
    last_evaluated_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    CONSTRAINT retention_policies_pkey PRIMARY KEY (id),
    CONSTRAINT uq_retention_policies_type_trigger UNIQUE (record_type, trigger_event)
);

CREATE TABLE IF NOT EXISTS saved_views (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entity_type character varying(20) NOT NULL,
    name character varying(100) NOT NULL,
    filters jsonb DEFAULT '{}'::jsonb NOT NULL,
    columns jsonb,
    shared boolean DEFAULT false NOT NULL,
    created_by uuid NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT saved_views_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS tags (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(50) NOT NULL,
    slug character varying(50) NOT NULL,
    color character varying(7),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tags_pkey PRIMARY KEY (id),
    CONSTRAINT uq_tag_slug UNIQUE (slug)
);

CREATE TABLE IF NOT EXISTS tariff_schedules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(100) NOT NULL,
    category character varying(20) NOT NULL,
    court_level character varying(30) NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    is_active boolean DEFAULT true NOT NULL,
    is_system boolean DEFAULT false NOT NULL,
    source character varying(100),
