    CONSTRAINT chk_trust_account_status CHECK ((status IN ('ACTIVE', 'CLOSED'))),
    CONSTRAINT chk_trust_account_threshold CHECK (((payment_approval_threshold IS NULL) OR (payment_approval_threshold > (0)::numeric))),
    CONSTRAINT chk_trust_account_type CHECK ((account_type IN ('GENERAL', 'INVESTMENT', 'SECTION_86'))),
