CREATE TABLE IF NOT EXISTS document_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(200) NOT NULL,
    slug character varying(200) NOT NULL,
    description text,
    category character varying(30) NOT NULL,
    primary_entity_type character varying(20) NOT NULL,
    css text,
    source character varying(20) DEFAULT 'ORG_CUSTOM'::character varying NOT NULL,
    source_template_id uuid,
    pack_id character varying(100),
    pack_template_key character varying(100),
    active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    required_context_fields jsonb,
    content jsonb,
    legacy_content text,
    format character varying(20) DEFAULT 'TIPTAP'::character varying NOT NULL,
    docx_s3_key character varying(500),
    docx_file_name character varying(255),
    docx_file_size bigint,
    discovered_fields jsonb,
    source_pack_install_id uuid,
    content_hash character varying(64),
    acceptance_eligible boolean DEFAULT false NOT NULL,
    CONSTRAINT chk_dt_category CHECK ((category IN ('ENGAGEMENT_LETTER', 'STATEMENT_OF_WORK', 'COVER_LETTER', 'PROJECT_SUMMARY', 'NDA', 'REPORT', 'COMPLIANCE', 'CLOSURE', 'OTHER'))),
    CONSTRAINT chk_dt_entity_type CHECK ((primary_entity_type IN ('PROJECT', 'CUSTOMER', 'INVOICE', 'ORGANIZATION'))),
    CONSTRAINT chk_dt_pack_fields CHECK ((((pack_id IS NULL) AND (pack_template_key IS NULL)) OR ((pack_id IS NOT NULL) AND (pack_template_key IS NOT NULL)))),
    CONSTRAINT chk_dt_slug_format CHECK (((slug)::text ~ '^[a-z][a-z0-9-]*$'::text)),
    CONSTRAINT chk_dt_source CHECK ((source IN ('PLATFORM', 'ORG_CUSTOM'))),
    CONSTRAINT chk_template_format CHECK ((format IN ('TIPTAP', 'DOCX'))),
    CONSTRAINT document_templates_pkey PRIMARY KEY (id),
    CONSTRAINT document_templates_slug_key UNIQUE (slug),
    CONSTRAINT document_templates_source_pack_install_id_fkey FOREIGN KEY (source_pack_install_id) REFERENCES pack_install(id) ON DELETE SET NULL,
    CONSTRAINT document_templates_source_template_id_fkey FOREIGN KEY (source_template_id) REFERENCES document_templates(id) ON DELETE SET NULL
);

