    CONSTRAINT chk_bank_stmt_format CHECK ((format IN ('CSV', 'OFX'))),
    CONSTRAINT chk_bank_stmt_period CHECK ((period_end >= period_start)),
    CONSTRAINT chk_bank_stmt_status CHECK ((status IN ('IMPORTED', 'MATCHING_IN_PROGRESS', 'MATCHED', 'RECONCILED'))),
