    CONSTRAINT template_clauses_clause_id_fkey FOREIGN KEY (clause_id) REFERENCES clauses(id) ON DELETE RESTRICT,
    CONSTRAINT template_clauses_template_id_fkey FOREIGN KEY (template_id) REFERENCES document_templates(id) ON DELETE CASCADE
);

