CREATE TABLE IF NOT EXISTS billing_rates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    member_id uuid,
    project_id uuid,
    customer_id uuid,
    currency character varying(3) NOT NULL,
    hourly_rate numeric(12,2) NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_billing_rate_currency_len CHECK ((char_length((currency)::text) = 3)),
    CONSTRAINT chk_billing_rate_dates CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT chk_billing_rate_positive CHECK ((hourly_rate > (0)::numeric)),
    CONSTRAINT chk_billing_rate_scope CHECK ((NOT ((project_id IS NOT NULL) AND (customer_id IS NOT NULL)))),
    CONSTRAINT billing_rates_pkey PRIMARY KEY (id),
    CONSTRAINT billing_rates_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE,
    CONSTRAINT billing_rates_member_id_fkey FOREIGN KEY (member_id) REFERENCES members(id),
    CONSTRAINT billing_rates_project_id_fkey FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
);

