    CONSTRAINT checklist_instances_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id),
    CONSTRAINT checklist_instances_template_id_fkey FOREIGN KEY (template_id) REFERENCES checklist_templates(id)
);

CREATE TABLE IF NOT EXISTS client_ledger_cards (
