    customer_id uuid NOT NULL,
    balance numeric(15,2) DEFAULT 0 NOT NULL,
    total_deposits numeric(15,2) DEFAULT 0 NOT NULL,
    total_payments numeric(15,2) DEFAULT 0 NOT NULL,
    total_fee_transfers numeric(15,2) DEFAULT 0 NOT NULL,
    total_interest_credited numeric(15,2) DEFAULT 0 NOT NULL,
    last_transaction_date date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_client_ledger_balance_non_negative CHECK ((balance >= (0)::numeric)),
    CONSTRAINT chk_client_ledger_deposits_non_negative CHECK ((total_deposits >= (0)::numeric)),
    CONSTRAINT chk_client_ledger_fee_transfers_non_negative CHECK ((total_fee_transfers >= (0)::numeric)),
    CONSTRAINT chk_client_ledger_interest_non_negative CHECK ((total_interest_credited >= (0)::numeric)),
    CONSTRAINT chk_client_ledger_payments_non_negative CHECK ((total_payments >= (0)::numeric)),
    CONSTRAINT client_ledger_cards_pkey PRIMARY KEY (id),
    CONSTRAINT uq_client_ledger_account_customer UNIQUE (trust_account_id, customer_id),
    CONSTRAINT client_ledger_cards_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id),
    CONSTRAINT client_ledger_cards_trust_account_id_fkey FOREIGN KEY (trust_account_id) REFERENCES trust_accounts(id)
);

