    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source character varying(20) DEFAULT 'INTERNAL'::character varying NOT NULL,
    CONSTRAINT chk_comment_entity_type CHECK ((entity_type IN ('TASK', 'DOCUMENT', 'PROJECT'))),
    CONSTRAINT chk_comment_visibility CHECK ((visibility IN ('INTERNAL', 'SHARED'))),
    CONSTRAINT comments_pkey PRIMARY KEY (id),
    CONSTRAINT comments_parent_id_fkey FOREIGN KEY (parent_id) REFERENCES comments(id) ON DELETE CASCADE,
    CONSTRAINT comments_project_id_fkey FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS court_dates (
