    status character varying(20) DEFAULT 'SCHEDULED'::character varying NOT NULL,
    outcome text,
    reminder_days integer DEFAULT 7 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT court_dates_pkey PRIMARY KEY (id),
    CONSTRAINT court_dates_created_by_fkey FOREIGN KEY (created_by) REFERENCES members(id),
    CONSTRAINT court_dates_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id),
