CREATE TABLE IF NOT EXISTS documents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid,
    file_name character varying(500) NOT NULL,
    content_type character varying(100),
    size bigint NOT NULL,
    s3_key character varying(1000) NOT NULL,
    status character varying(50) DEFAULT 'PENDING'::character varying NOT NULL,
    uploaded_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    uploaded_by uuid NOT NULL,
    scope character varying(20) DEFAULT 'PROJECT'::character varying NOT NULL,
    customer_id uuid,
    visibility character varying(20) DEFAULT 'INTERNAL'::character varying NOT NULL,
    source character varying(30) DEFAULT 'MANUAL'::character varying NOT NULL,
    ai_execution_id uuid,
    correspondence_id uuid,
    CONSTRAINT chk_documents_provenance CHECK (((((source)::text = 'AI_GENERATED'::text) AND (ai_execution_id IS NOT NULL)) OR (((source)::text <> 'AI_GENERATED'::text) AND (ai_execution_id IS NULL)))),
    CONSTRAINT chk_documents_scope_fks CHECK (((((scope)::text = 'PROJECT'::text) AND (project_id IS NOT NULL)) OR (((scope)::text = 'ORG'::text) AND (project_id IS NULL) AND (customer_id IS NULL)) OR (((scope)::text = 'CUSTOMER'::text) AND (customer_id IS NOT NULL)))),
    CONSTRAINT documents_pkey PRIMARY KEY (id),
    CONSTRAINT documents_ai_execution_id_fkey FOREIGN KEY (ai_execution_id) REFERENCES ai_executions(id),
    CONSTRAINT documents_correspondence_id_fkey FOREIGN KEY (correspondence_id) REFERENCES correspondence(id),
    CONSTRAINT documents_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT,
    CONSTRAINT documents_project_id_fkey FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
    CONSTRAINT fk_documents_uploaded_by FOREIGN KEY (uploaded_by) REFERENCES members(id)
);

CREATE TABLE IF NOT EXISTS invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    customer_id uuid NOT NULL,
    invoice_number character varying(20),
    status character varying(20) DEFAULT 'DRAFT'::character varying NOT NULL,
    currency character varying(3) NOT NULL,
    issue_date date,
    due_date date,
    subtotal numeric(14,2) DEFAULT 0 NOT NULL,
    tax_amount numeric(14,2) DEFAULT 0 NOT NULL,
    total numeric(14,2) DEFAULT 0 NOT NULL,
    notes text,
    payment_terms character varying(100),
    payment_reference character varying(255),
    paid_at timestamp with time zone,
    customer_name character varying(255) NOT NULL,
    customer_email character varying(255),
    customer_address text,
    org_name character varying(255) NOT NULL,
    created_by uuid NOT NULL,
    approved_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    custom_fields jsonb DEFAULT '{}'::jsonb NOT NULL,
    applied_field_groups jsonb DEFAULT '[]'::jsonb NOT NULL,
    payment_session_id character varying(255),
    payment_url character varying(1024),
    payment_destination character varying(50) DEFAULT 'OPERATING'::character varying NOT NULL,
    billing_run_id uuid,
    po_number character varying(100),
    tax_type character varying(20),
    billing_period_start date,
    billing_period_end date,
    CONSTRAINT chk_invoice_currency_len CHECK ((char_length((currency)::text) = 3)),
    CONSTRAINT chk_invoice_status CHECK ((status IN ('DRAFT', 'APPROVED', 'SENT', 'PAID', 'VOID'))),
    CONSTRAINT chk_invoices_payment_destination CHECK ((payment_destination IN ('OPERATING', 'TRUST'))),
    CONSTRAINT invoices_pkey PRIMARY KEY (id),
    CONSTRAINT invoices_approved_by_fkey FOREIGN KEY (approved_by) REFERENCES members(id),
    CONSTRAINT invoices_billing_run_id_fkey FOREIGN KEY (billing_run_id) REFERENCES billing_runs(id),
    CONSTRAINT invoices_created_by_fkey FOREIGN KEY (created_by) REFERENCES members(id),
    CONSTRAINT invoices_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id)
);

CREATE TABLE IF NOT EXISTS matter_closure_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    closed_by uuid NOT NULL,
    closed_at timestamp with time zone NOT NULL,
    reason character varying(40) NOT NULL,
    notes text,
    gate_report jsonb NOT NULL,
    override_used boolean DEFAULT false NOT NULL,
    override_justification text,
    closure_letter_document_id uuid,
    reopened_at timestamp with time zone,
    reopened_by uuid,
    reopen_notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_matter_closure_log_override_justification CHECK (((override_used = false) OR ((override_justification IS NOT NULL) AND (length(TRIM(BOTH FROM override_justification)) >= 20)))),
    CONSTRAINT ck_matter_closure_log_reason CHECK ((reason IN ('CONCLUDED', 'CLIENT_TERMINATED', 'REFERRED_OUT', 'OTHER'))),
    CONSTRAINT ck_matter_closure_log_reopen_consistent CHECK ((((reopened_at IS NULL) AND (reopened_by IS NULL) AND (reopen_notes IS NULL)) OR ((reopened_at IS NOT NULL) AND (reopened_by IS NOT NULL) AND (reopen_notes IS NOT NULL)))),
    CONSTRAINT matter_closure_log_pkey PRIMARY KEY (id),
    CONSTRAINT fk_matter_closure_log_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE RESTRICT
);

