    prescription_type character varying(30) NOT NULL,
    custom_years integer,
    prescription_date date NOT NULL,
    interruption_date date,
    interruption_reason character varying(200),
    status character varying(20) DEFAULT 'RUNNING'::character varying NOT NULL,
    notes text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT prescription_trackers_pkey PRIMARY KEY (id),
    CONSTRAINT prescription_trackers_created_by_fkey FOREIGN KEY (created_by) REFERENCES members(id),
    CONSTRAINT prescription_trackers_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id),
    CONSTRAINT prescription_trackers_project_id_fkey FOREIGN KEY (project_id) REFERENCES projects(id)
);

CREATE TABLE IF NOT EXISTS project_budgets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    budget_hours numeric(10,2),
    budget_amount numeric(14,2),
    budget_currency character varying(3),
    alert_threshold_pct integer DEFAULT 80 NOT NULL,
    threshold_notified boolean DEFAULT false NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT chk_budget_amount_positive CHECK (((budget_amount IS NULL) OR (budget_amount > (0)::numeric))),
    CONSTRAINT chk_budget_at_least_one CHECK (((budget_hours IS NOT NULL) OR (budget_amount IS NOT NULL))),
    CONSTRAINT chk_budget_currency_len CHECK (((budget_currency IS NULL) OR (char_length((budget_currency)::text) = 3))),
    CONSTRAINT chk_budget_currency_required CHECK (((budget_amount IS NULL) OR (budget_currency IS NOT NULL))),
    CONSTRAINT chk_budget_hours_positive CHECK (((budget_hours IS NULL) OR (budget_hours > (0)::numeric))),
    CONSTRAINT chk_budget_threshold_range CHECK (((alert_threshold_pct >= 50) AND (alert_threshold_pct <= 100))),
    CONSTRAINT project_budgets_pkey PRIMARY KEY (id),
    CONSTRAINT project_budgets_project_id_fkey FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
);

