    CONSTRAINT project_members_added_by_fkey FOREIGN KEY (added_by) REFERENCES members(id),
    CONSTRAINT project_members_member_id_fkey FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE,
    CONSTRAINT project_members_project_id_fkey FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    title character varying(500) NOT NULL,
    description text,
    status character varying(20) DEFAULT 'OPEN'::character varying NOT NULL,
    priority character varying(20) DEFAULT 'MEDIUM'::character varying NOT NULL,
    type character varying(100),
    assignee_id uuid,
    created_by uuid NOT NULL,
    due_date date,
    version integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    customer_visible boolean DEFAULT false NOT NULL,
    custom_fields jsonb DEFAULT '{}'::jsonb,
    applied_field_groups jsonb,
