    estimated_hours numeric(8,2),
    CONSTRAINT tasks_priority_check CHECK ((priority IN ('LOW', 'MEDIUM', 'HIGH', 'URGENT'))),
    CONSTRAINT tasks_status_check CHECK ((status IN ('OPEN', 'IN_PROGRESS', 'DONE', 'CANCELLED'))),
    CONSTRAINT tasks_pkey PRIMARY KEY (id),
    CONSTRAINT tasks_assignee_id_fkey FOREIGN KEY (assignee_id) REFERENCES members(id) ON DELETE SET NULL,
    CONSTRAINT tasks_created_by_fkey FOREIGN KEY (created_by) REFERENCES members(id),
