CREATE TABLE IF NOT EXISTS checklist_instance_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    instance_id uuid NOT NULL,
    template_item_id uuid NOT NULL,
    name character varying(300) NOT NULL,
    description text,
    sort_order integer NOT NULL,
    required boolean NOT NULL,
    requires_document boolean NOT NULL,
    required_document_label character varying(200),
    status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    completed_at timestamp with time zone,
    completed_by uuid,
    notes text,
    document_id uuid,
    depends_on_item_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    applicable_entity_types jsonb,
    verification_provider character varying(30),
    verification_reference character varying(200),
    verification_status character varying(20),
    verified_at timestamp with time zone,
    verification_metadata jsonb,
    CONSTRAINT chk_verification_status CHECK (((verification_status IS NULL) OR (verification_status IN ('VERIFIED', 'NOT_VERIFIED', 'NEEDS_REVIEW')))),
    CONSTRAINT checklist_instance_items_pkey PRIMARY KEY (id),
    CONSTRAINT uq_checklist_instance_items_instance_template UNIQUE (instance_id, template_item_id),
