    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_trust_txn_amount_positive CHECK ((amount > (0)::numeric)),
    CONSTRAINT chk_trust_txn_customer_required CHECK ((((transaction_type)::text = 'INTEREST_LPFF'::text) OR (customer_id IS NOT NULL))),
    CONSTRAINT chk_trust_txn_status CHECK ((status IN ('RECORDED', 'AWAITING_APPROVAL', 'APPROVED', 'REJECTED', 'REVERSED'))),
    CONSTRAINT chk_trust_txn_type CHECK ((transaction_type IN ('DEPOSIT', 'PAYMENT', 'TRANSFER_IN', 'TRANSFER_OUT', 'FEE_TRANSFER', 'REFUND', 'INTEREST_CREDIT', 'INTEREST_LPFF', 'REVERSAL'))),
    CONSTRAINT trust_transactions_pkey PRIMARY KEY (id),
    CONSTRAINT fk_trust_txn_bank_line FOREIGN KEY (bank_statement_line_id) REFERENCES bank_statement_lines(id),
    CONSTRAINT trust_transactions_counterparty_customer_id_fkey FOREIGN KEY (counterparty_customer_id) REFERENCES customers(id),
    CONSTRAINT trust_transactions_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id),
    CONSTRAINT trust_transactions_invoice_id_fkey FOREIGN KEY (invoice_id) REFERENCES invoices(id),
    CONSTRAINT trust_transactions_project_id_fkey FOREIGN KEY (project_id) REFERENCES projects(id),
    CONSTRAINT trust_transactions_recorded_by_fkey FOREIGN KEY (recorded_by) REFERENCES members(id),
    CONSTRAINT trust_transactions_reversal_of_fkey FOREIGN KEY (reversal_of) REFERENCES trust_transactions(id),
    CONSTRAINT trust_transactions_reversed_by_id_fkey FOREIGN KEY (reversed_by_id) REFERENCES trust_transactions(id),
    CONSTRAINT trust_transactions_trust_account_id_fkey FOREIGN KEY (trust_account_id) REFERENCES trust_accounts(id)
);

