    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    investment_basis character varying(20) DEFAULT 'FIRM_DISCRETION'::character varying NOT NULL,
    CONSTRAINT chk_investment_basis CHECK ((investment_basis IN ('FIRM_DISCRETION', 'CLIENT_INSTRUCTION'))),
    CONSTRAINT chk_trust_invest_earned CHECK ((interest_earned >= (0)::numeric)),
    CONSTRAINT chk_trust_invest_maturity CHECK (((maturity_date IS NULL) OR (maturity_date >= deposit_date))),
    CONSTRAINT chk_trust_invest_principal CHECK ((principal > (0)::numeric)),
    CONSTRAINT chk_trust_invest_rate CHECK (((interest_rate >= (0)::numeric) AND (interest_rate <= (1)::numeric))),
    CONSTRAINT chk_trust_invest_status CHECK ((status IN ('ACTIVE', 'MATURED', 'WITHDRAWN'))),
    CONSTRAINT trust_investments_pkey PRIMARY KEY (id),
    CONSTRAINT trust_investments_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id),
    CONSTRAINT trust_investments_deposit_transaction_id_fkey FOREIGN KEY (deposit_transaction_id) REFERENCES trust_transactions(id),
    CONSTRAINT trust_investments_trust_account_id_fkey FOREIGN KEY (trust_account_id) REFERENCES trust_accounts(id),
    CONSTRAINT trust_investments_withdrawal_transaction_id_fkey FOREIGN KEY (withdrawal_transaction_id) REFERENCES trust_transactions(id)
);

