    CONSTRAINT chk_invoice_line_quantity_positive CHECK ((quantity > (0)::numeric)),
    CONSTRAINT chk_invoice_line_unit_price_non_negative CHECK ((unit_price >= (0)::numeric)),
    CONSTRAINT invoice_lines_line_source_check CHECK (((line_source IS NULL) OR (line_source IN ('TIME', 'RETAINER', 'EXPENSE', 'MANUAL', 'FIXED_FEE', 'TARIFF', 'DISBURSEMENT')))),
    CONSTRAINT invoice_lines_line_type_check CHECK ((line_type IN ('TIME', 'EXPENSE', 'MANUAL', 'FIXED_FEE', 'TARIFF', 'DISBURSEMENT'))),
    CONSTRAINT invoice_lines_pkey PRIMARY KEY (id),
    CONSTRAINT invoice_lines_invoice_id_fkey FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE CASCADE,
    CONSTRAINT invoice_lines_project_id_fkey FOREIGN KEY (project_id) REFERENCES projects(id),
    CONSTRAINT invoice_lines_tax_rate_id_fkey FOREIGN KEY (tax_rate_id) REFERENCES tax_rates(id),
    CONSTRAINT invoice_lines_time_entry_id_fkey FOREIGN KEY (time_entry_id) REFERENCES time_entries(id)
);

CREATE TABLE IF NOT EXISTS legal_disbursements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    category character varying(30) NOT NULL,
    description text NOT NULL,
    amount numeric(15,2) NOT NULL,
    vat_treatment character varying(30) NOT NULL,
    vat_amount numeric(15,2) DEFAULT 0 NOT NULL,
    payment_source character varying(20) NOT NULL,
    trust_transaction_id uuid,
    incurred_date date NOT NULL,
    supplier_name character varying(200) NOT NULL,
    supplier_reference character varying(100),
    receipt_document_id uuid,
    approval_status character varying(20) DEFAULT 'DRAFT'::character varying NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    approval_notes text,
    billing_status character varying(20) DEFAULT 'UNBILLED'::character varying NOT NULL,
    invoice_line_id uuid,
    write_off_reason text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_legal_disbursements_amount_positive CHECK ((amount > (0)::numeric)),
    CONSTRAINT ck_legal_disbursements_approval_status CHECK ((approval_status IN ('DRAFT', 'PENDING_APPROVAL', 'APPROVED', 'REJECTED'))),
    CONSTRAINT ck_legal_disbursements_billing_status CHECK ((billing_status IN ('UNBILLED', 'BILLED', 'WRITTEN_OFF'))),
    CONSTRAINT ck_legal_disbursements_category CHECK ((category IN ('SHERIFF_FEES', 'COUNSEL_FEES', 'SEARCH_FEES', 'DEEDS_OFFICE_FEES', 'COURT_FEES', 'ADVOCATE_FEES', 'EXPERT_WITNESS', 'TRAVEL', 'OTHER'))),
    CONSTRAINT ck_legal_disbursements_payment_source CHECK ((payment_source IN ('OFFICE_ACCOUNT', 'TRUST_ACCOUNT'))),
    CONSTRAINT ck_legal_disbursements_trust_link CHECK (((((payment_source)::text = 'TRUST_ACCOUNT'::text) AND (trust_transaction_id IS NOT NULL)) OR (((payment_source)::text = 'OFFICE_ACCOUNT'::text) AND (trust_transaction_id IS NULL)))),
    CONSTRAINT ck_legal_disbursements_vat_treatment CHECK ((vat_treatment IN ('STANDARD_15', 'ZERO_RATED_PASS_THROUGH', 'EXEMPT'))),
    CONSTRAINT ck_legal_disbursements_writeoff_reason CHECK ((((billing_status)::text <> 'WRITTEN_OFF'::text) OR (write_off_reason IS NOT NULL))),
    CONSTRAINT legal_disbursements_pkey PRIMARY KEY (id),
    CONSTRAINT legal_disbursements_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT,
    CONSTRAINT legal_disbursements_invoice_line_id_fkey FOREIGN KEY (invoice_line_id) REFERENCES invoice_lines(id) ON DELETE SET NULL,
    CONSTRAINT legal_disbursements_project_id_fkey FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE RESTRICT,
    CONSTRAINT legal_disbursements_receipt_document_id_fkey FOREIGN KEY (receipt_document_id) REFERENCES documents(id) ON DELETE SET NULL,
    CONSTRAINT legal_disbursements_trust_transaction_id_fkey FOREIGN KEY (trust_transaction_id) REFERENCES trust_transactions(id) ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- Foreign keys closing FK cycles (cannot be inline: the target table is created later)
-- ---------------------------------------------------------------------

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
    JOIN pg_namespace n ON c.connamespace = n.oid
    WHERE c.conname = 'bank_statement_lines_trust_transaction_id_fkey'
      AND n.nspname = current_schema()
  ) THEN
    ALTER TABLE bank_statement_lines
        ADD CONSTRAINT bank_statement_lines_trust_transaction_id_fkey FOREIGN KEY (trust_transaction_id) REFERENCES trust_transactions(id);
  END IF;
END $$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
    JOIN pg_namespace n ON c.connamespace = n.oid
    WHERE c.conname = 'invoice_lines_disbursement_id_fkey'
      AND n.nspname = current_schema()
  ) THEN
    ALTER TABLE invoice_lines
        ADD CONSTRAINT invoice_lines_disbursement_id_fkey FOREIGN KEY (disbursement_id) REFERENCES legal_disbursements(id) ON DELETE RESTRICT;
  END IF;
END $$;

-- ---------------------------------------------------------------------
-- Indexes
-- ---------------------------------------------------------------------

CREATE UNIQUE INDEX IF NOT EXISTS idx_acceptance_requests_active_unique ON acceptance_requests USING btree (generated_document_id, portal_contact_id) WHERE (status IN ('PENDING', 'SENT', 'VIEWED'));
CREATE INDEX IF NOT EXISTS idx_acceptance_requests_customer_status ON acceptance_requests USING btree (customer_id, status);
CREATE INDEX IF NOT EXISTS idx_acceptance_requests_document ON acceptance_requests USING btree (generated_document_id);
CREATE INDEX IF NOT EXISTS idx_acceptance_requests_expiry ON acceptance_requests USING btree (status, expires_at) WHERE (status IN ('PENDING', 'SENT', 'VIEWED'));
CREATE UNIQUE INDEX IF NOT EXISTS idx_acceptance_requests_token ON acceptance_requests USING btree (request_token);
CREATE INDEX IF NOT EXISTS idx_action_executions_scheduled ON action_executions USING btree (scheduled_for, status) WHERE ((status)::text = 'SCHEDULED'::text);
CREATE INDEX IF NOT EXISTS idx_adverse_parties_aliases_trgm ON adverse_parties USING gin (aliases gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_adverse_parties_id_number ON adverse_parties USING btree (id_number) WHERE (id_number IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_adverse_parties_name_trgm ON adverse_parties USING gin (name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_adverse_parties_reg_number ON adverse_parties USING btree (registration_number) WHERE (registration_number IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_adverse_party_links_customer ON adverse_party_links USING btree (customer_id);
CREATE INDEX IF NOT EXISTS idx_adverse_party_links_party ON adverse_party_links USING btree (adverse_party_id);
CREATE INDEX IF NOT EXISTS idx_adverse_party_links_project ON adverse_party_links USING btree (project_id);
