CREATE INDEX IF NOT EXISTS ix_matter_closure_log_override_used ON matter_closure_log USING btree (project_id) WHERE (override_used = true);
CREATE INDEX IF NOT EXISTS ix_matter_closure_log_project_closed ON matter_closure_log USING btree (project_id, closed_at DESC);
CREATE INDEX IF NOT EXISTS ix_projects_retention_clock_started_at ON projects USING btree (retention_clock_started_at) WHERE (retention_clock_started_at IS NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS uq_compliance_audit_reports_single_published ON compliance_audit_reports USING btree (status) WHERE ((status)::text = 'PUBLISHED'::text);
CREATE UNIQUE INDEX IF NOT EXISTS uq_field_date_notification_dedup ON field_date_notification_log USING btree (entity_type, entity_id, field_name, days_until);
CREATE UNIQUE INDEX IF NOT EXISTS uq_interest_run_no_overlap ON interest_runs USING btree (trust_account_id, period_start, period_end) WHERE (status IN ('DRAFT', 'APPROVED', 'POSTED'));
CREATE UNIQUE INDEX IF NOT EXISTS uq_pending_invitation_email_pending ON pending_invitations USING btree (email) WHERE ((status)::text = 'PENDING'::text);
CREATE UNIQUE INDEX IF NOT EXISTS uq_saved_view_personal_name ON saved_views USING btree (entity_type, name, created_by) WHERE (shared = false);
CREATE UNIQUE INDEX IF NOT EXISTS uq_saved_view_shared_name ON saved_views USING btree (entity_type, name) WHERE (shared = true);
CREATE UNIQUE INDEX IF NOT EXISTS ux_billing_rates_member_default_open ON billing_rates USING btree (member_id) WHERE ((member_id IS NOT NULL) AND (project_id IS NULL) AND (customer_id IS NULL) AND (effective_to IS NULL));
CREATE UNIQUE INDEX IF NOT EXISTS ux_collection_activity_invoice_stage ON collection_activities USING btree (invoice_id, stage);
CREATE UNIQUE INDEX IF NOT EXISTS ux_correspondence_message_id ON correspondence USING btree (message_id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_cost_rates_member_default_open ON cost_rates USING btree (member_id) WHERE (effective_to IS NULL);

-- ---------------------------------------------------------------------
-- Functions + triggers (audit_events append-only guard)
-- ---------------------------------------------------------------------

CREATE OR REPLACE FUNCTION prevent_audit_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'audit_events rows cannot be deleted';
END;
$$;

CREATE OR REPLACE FUNCTION prevent_audit_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'audit_events rows cannot be updated';
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger t
    JOIN pg_class c ON t.tgrelid = c.oid
    JOIN pg_namespace n ON c.relnamespace = n.oid
    WHERE t.tgname = 'audit_events_no_delete'
      AND n.nspname = current_schema()
  ) THEN
    EXECUTE 'CREATE TRIGGER audit_events_no_delete BEFORE DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION prevent_audit_delete()';
  END IF;
END $$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger t
    JOIN pg_class c ON t.tgrelid = c.oid
    JOIN pg_namespace n ON c.relnamespace = n.oid
    WHERE t.tgname = 'audit_events_no_update'
      AND n.nspname = current_schema()
  ) THEN
    EXECUTE 'CREATE TRIGGER audit_events_no_update BEFORE UPDATE ON audit_events FOR EACH ROW EXECUTE FUNCTION prevent_audit_update()';
  END IF;
END $$;

